import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date | null;
  onChange?: (value: Date | null) => void;
};

const startOfDay = (date: Date) => new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (days: number) => {
  const date = startOfDay(new Date());
  date.setDate(date.getDate() - days);
  return date;
};

const isSameDay = (a: Date | null | undefined, b: Date) =>
  a instanceof Date && startOfDay(a).getTime() === b.getTime();

export default function ReportDatePicker({ value, onChange }: ReportDatePickerProps) {
  const [internalDate, setInternalDate] = useState<Date | null>(null);
  const selected = value === undefined ? internalDate : value;

  const select = (next: Date | null) => {
    if (value === undefined) setInternalDate(next);
    onChange?.(next);
  };

  const presets = [
    { key: 'today', label: 'Сегодня', date: shiftDays(0) },
    { key: 'yesterday', label: 'Вчера', date: shiftDays(1) },
    { key: 'week', label: 'Неделя назад', date: shiftDays(7) },
  ];

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {presets.map((preset) => (
          <JxChip
            key={preset.key}
            active={isSameDay(selected, preset.date)}
            role="button"
            tabIndex={0}
            onClick={() => select(preset.date)}
            onKeyDown={(event) => {
              if (event.key === 'Enter' || event.key === ' ') {
                event.preventDefault();
                select(preset.date);
              }
            }}
          >
            {preset.label}
          </JxChip>
        ))}
      </div>
      <JxCalendar locale="ru-RU" value={selected} onValueChange={select} />
    </div>
  );
}

